installer-gui-script.script:
function resolve_present() {
  // Resolve creates this folder when it is installed; without it there is
  // no menu for the script to appear in.
  if (system.files.fileExistsAtPath('/Library/Application Support/Blackmagic Design/DaVinci Resolve/Fusion/Scripts')) return true;
  my.result.title = 'DaVinci Resolve is not installed';
  my.result.message = 'Install DaVinci Resolve from blackmagicdesign.com first, then run this installer again.';
  my.result.type = 'Fatal';
  return false;
}
